def compare_phase_images(baseline, current, *, interpolated, phase, foil=False, patterned=False, material=None, pose="idle"):
    if any(type(value) is not bool for value in (interpolated, foil, patterned)):
        raise ValueError("explicit interpolation, foil and pattern policies are required")
    material = ("cross" if patterned else "plain") if material is None else material
    if (material not in SHIELD_ANIMATION_SPRITES and material not in ("combined", "mixed", "periods")) or patterned != (material != "plain"):
        raise ValueError("shield pixel oracle requires matching material and item components")
    if pose != "idle":
        key = (pose, material, foil, interpolated, phase)
        if pose not in ("blocking", "blocking-offhand") or type(phase) is not int or key not in FROZEN_POSE_REFERENCES:
            raise ValueError("no independent Frozen pixel oracle for this shield pose")
        probes, regions = FROZEN_POSE_REFERENCES[key]
        result = _compare_images(baseline, current, probes, "shield-animation-pose-pixels-v1", regions)
        result.update(phase=phase, pose=pose, material=material, foil=foil, patterned=patterned,
                      interpolated=interpolated, capability_admitted=False)
        return result
    if material not in ("plain", "cross"):
        key = (material,foil,interpolated,phase)
        if type(phase) is not int or key not in FROZEN_MATERIAL_PROBES:
            raise ValueError("no independent Frozen pixel oracle for this material and phase")
        result = _compare_images(baseline,current,FROZEN_MATERIAL_PROBES[key],
                                "shield-animation-material-phase-pixels-v1")
        result.update(phase=phase,duration=17,interpolated=interpolated,foil=foil,
                      patterned=patterned,material=material,capability_admitted=False)
        return result
    if foil or patterned:
        if type(phase) is not int or (patterned,foil,interpolated,phase) not in FROZEN_VARIANT_PROBES:
            raise ValueError("no independent Frozen pixel oracle for this shield variant and phase")
        result = _compare_images(baseline,current,FROZEN_VARIANT_PROBES[(patterned,foil,interpolated,phase)],
                                "shield-animation-variant-phase-pixels-v1")
        result.update(phase=phase,duration=17,interpolated=interpolated,foil=foil,patterned=patterned,
                      capability_admitted=False)
        return result
    if type(phase) is not int or (phase != 4 and not (phase in (0, 9) and interpolated)):
        raise ValueError("no independent Frozen pixel oracle for this phase")
    colors = (FROZEN_PHASE_FOUR[interpolated] if phase == 4 else
              FROZEN_PHASE_NINE_INTERPOLATED if phase == 9 else FROZEN_PHASE_ZERO_INTERPOLATED)
    probes = [(name, x, y, [color] * 9)
              for (name, x, y, _), color in zip(BASE_PROBES, colors)]
    result = _compare_images(baseline, current, probes, "shield-animation-phase-pixels-v1")
    result.update(phase=phase, duration=17, interpolated=interpolated,
                  capability_admitted=False)
    return result


def compare_phase_four_paths(baseline, current, *, interpolated):
    return compare_phase_paths(baseline, current, interpolated=interpolated, phase=4)


def compare_phase_paths(baseline, current, *, interpolated, phase, foil=False, patterned=False, material=None, pose="idle"):
    with Image.open(baseline) as frozen, Image.open(current) as rust:
        return compare_phase_images(frozen, rust, interpolated=interpolated, phase=phase, foil=foil, patterned=patterned, material=material, pose=pose)
